"""
Task T019b: Calculate Preprocessing Success Rate.

This script calculates the preprocessing success rate based on the
'preprocessing_stats.json' artifact generated by T017b.

It verifies the existence of the artifact, calculates the success rate
(successful_subjects / total_subjects), and writes the result to
data/processed/success_rate_report.json.

Dependency: T017b (must have generated data/processed/preprocessing_stats.json)
"""
import os
import sys
import json
from pathlib import Path
from typing import Dict, Any, Optional

# Ensure project root is in path for imports if run as script
PROJECT_ROOT = Path(__file__).resolve().parent.parent
DATA_PROCESSED_DIR = PROJECT_ROOT / "data" / "processed"
INPUT_FILE = DATA_PROCESSED_DIR / "preprocessing_stats.json"
OUTPUT_FILE = DATA_PROCESSED_DIR / "success_rate_report.json"

def load_preprocessing_stats() -> Optional[Dict[str, Any]]:
    """Load the preprocessing stats JSON generated by T017b."""
    if not INPUT_FILE.exists():
        print(f"ERROR: Required artifact not found: {INPUT_FILE}")
        print("Dependency T017b (Generate Preprocessing Stats) has not been executed successfully.")
        return None
    
    try:
        with open(INPUT_FILE, 'r') as f:
            data = json.load(f)
        
        # Validate schema
        required_keys = ["total_subjects", "successful_subjects", "success_rate_percentage"]
        for key in required_keys:
            if key not in data:
                print(f"ERROR: Missing required key '{key}' in {INPUT_FILE}")
                return None
        
        return data
    except json.JSONDecodeError as e:
        print(f"ERROR: Invalid JSON in {INPUT_FILE}: {e}")
        return None

def calculate_success_rate(stats: Dict[str, Any]) -> Dict[str, Any]:
    """
    Calculate and validate the success rate.
    
    Returns a dictionary with the calculated metrics and status.
    """
    total = stats.get("total_subjects", 0)
    successful = stats.get("successful_subjects", 0)
    reported_rate = stats.get("success_rate_percentage", 0.0)

    if total == 0:
        calculated_rate = 0.0
        status = "HALT_CONDITION_MET"
        message = "Total subjects is 0; success rate is undefined (0%)."
    else:
        calculated_rate = (successful / total) * 100.0
        # Check for consistency with reported rate (allow small float tolerance)
        if abs(calculated_rate - reported_rate) > 0.01:
            status = "MISMATCH_WARNING"
            message = f"Calculated rate ({calculated_rate:.2f}%) differs from reported rate ({reported_rate:.2f}%)."
        else:
            status = "VERIFIED"
            message = "Success rate verified successfully."

    return {
        "total_subjects": total,
        "successful_subjects": successful,
        "calculated_success_rate_percent": round(calculated_rate, 2),
        "reported_success_rate_percent": reported_rate,
        "status": status,
        "message": message,
        "artifact_source": str(INPUT_FILE)
    }

def write_report(report_data: Dict[str, Any]) -> bool:
    """Write the success rate report to the output JSON file."""
    try:
        # Ensure directory exists
        OUTPUT_FILE.parent.mkdir(parents=True, exist_ok=True)
        
        with open(OUTPUT_FILE, 'w') as f:
            json.dump(report_data, f, indent=2)
        
        print(f"SUCCESS: Report written to {OUTPUT_FILE}")
        return True
    except IOError as e:
        print(f"ERROR: Failed to write report to {OUTPUT_FILE}: {e}")
        return False

def main():
    """Main entry point for T019b."""
    print(f"--- T019b: Calculating Preprocessing Success Rate ---")
    print(f"Input: {INPUT_FILE}")
    print(f"Output: {OUTPUT_FILE}")
    
    # Load stats from T017b
    stats = load_preprocessing_stats()
    if stats is None:
        # Fail loudly as per constraints
        sys.exit(1)
    
    # Calculate metrics
    report = calculate_success_rate(stats)
    
    # Write output
    if not write_report(report):
        sys.exit(1)
    
    print(f"Task T019b completed. Status: {report['status']}")
    if report['status'] != "VERIFIED":
        print(f"Warning: {report['message']}")
    
    return 0

if __name__ == "__main__":
    sys.exit(main())
